INT                        // RETURN: cost of object
OBJS_GetCost (
OBJ_TYPE type              // INPUT : OBJ type
);

/***************************************************************************
OBJS_GetResale () - Returns The game Resale Value of an object
 ***************************************************************************/
INT                        // RETURN: cost of object
OBJS_GetResale (
OBJ_TYPE type              // INPUT : OBJ type
);

